// returns the index of the chosen action (argmax of the output layer)
static int crawler_small_act(const float *obs) {
  float a[32], c[32];
  for (int i = 0; i < 27; i++) a[i] = (obs[i] - crawler_small_mu[i]) / crawler_small_sd[i];
  for (int o = 0; o < 32; o++) {
    float s = crawler_small_b0[o];
    for (int k = 0; k < 27; k++) s += crawler_small_W0[o][k] * a[k];
    c[o] = tanhf(s);
  }
  for (int o = 0; o < 32; o++) a[o] = c[o];
  for (int o = 0; o < 32; o++) {
    float s = crawler_small_b1[o];
    for (int k = 0; k < 32; k++) s += crawler_small_W1[o][k] * a[k];
    c[o] = tanhf(s);
  }
  for (int o = 0; o < 32; o++) a[o] = c[o];
  for (int o = 0; o < 5; o++) {
    float s = crawler_small_b2[o];
    for (int k = 0; k < 32; k++) s += crawler_small_W2[o][k] * a[k];
    c[o] = s;
  }
  for (int o = 0; o < 5; o++) a[o] = c[o];
  int best = 0; for (int o = 1; o < 5; o++) if (a[o] > a[best]) best = o;
  return best;
}
